function first(name) { return $(name).first().json; }
function one(json) { return [{json}]; }
function normalize(text) { return text.replace(/\r\n?/g,'\n'); }
function words(text) { return text.split(/[\u0009-\u000d\u001c-\u0020\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+/u).filter(Boolean).length; }
function indiaToday() {
  const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));
  return `${p.year}-${p.month}-${p.day}`;
}
function isoDate(value) {
  assert(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value),'invalid_date');
  const d=new Date(value+'T00:00:00Z');
  assert(Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value,'invalid_date');
  return value;
}
function failure(e) {
  const known=/^(invalid_|missing_|blocked_|role_|source_|provider_|model_|usage_|critic_|letter_|mcp_|configuration_|verification_)[a-z0-9_]+$/;
  const error_code=known.test(e?.message||'')?e.message:'workflow_stage_failed';
  const http_status=error_code==='provider_throttled'?429:
    /^(invalid_|blocked_|role_expired|role_not_found)/.test(error_code)?422:502;
  return one({failed:true,http_status,body:{status:'failed',error_code,
    message:'The coaching pipeline could not complete this request. No application was approved or saved.'}});
}
// Supports raw MCP, JSON-RPC, n8n parsed text blocks and explicit single-result wrappers.
// No payload is accepted without the downstream role/date/hash evidence checks.
function mcpObject(value,depth=0) {
  assert(depth<12,'mcp_invalid_envelope');
  if(typeof value==='string') {
    assert(value.length<=200000,'mcp_invalid_envelope');
    let parsed;try {parsed=JSON.parse(value);} catch {fail('mcp_invalid_json');}
    return mcpObject(parsed,depth+1);
  }
  assert(value&&typeof value==='object'&&!value.isError&&!value.error,'mcp_tool_failed');
  if(Array.isArray(value)) {
    assert(value.length===1,'mcp_ambiguous_result');
    return mcpObject(value[0],depth+1);
  }
  if(typeof value.ok==='boolean')return value;
  if(value.type==='text'&&Object.hasOwn(value,'text'))return mcpObject(value.text,depth+1);
  if(Object.hasOwn(value,'structuredContent')&&value.structuredContent!=null)
    return mcpObject(value.structuredContent,depth+1);
  if(Object.hasOwn(value,'content')) {
    const blocks=Array.isArray(value.content)?value.content:[value.content];
    const text=blocks.filter(c=>c&&c.type==='text'&&Object.hasOwn(c,'text'));
    assert(text.length===1&&blocks.length===1,'mcp_ambiguous_result');
    return mcpObject(text[0].text,depth+1);
  }
  const wrappers=['json','response','result','output','data'].filter(k=>Object.hasOwn(value,k)&&value[k]!=null);
  assert(wrappers.length<=1,'mcp_ambiguous_result');
  if(wrappers.length===1)return mcpObject(value[wrappers[0]],depth+1);
  fail('mcp_invalid_envelope');
}
function httpBody(response) {
  assert(response&&!response.error,'provider_connection_failed');
  if (response.statusCode===429) fail('provider_throttled');
  assert(response.statusCode===200,'provider_http_failed');
  assert(response.body&&typeof response.body==='object','provider_invalid_body');
  return response.body;
}
function generation(response,previous) {
  const b=httpBody(response), c=b.candidates;
  assert(Array.isArray(c)&&c.length===1&&c[0].finishReason==='STOP','model_incomplete_output');
  const parts=c[0].content?.parts;
  assert(Array.isArray(parts)&&parts.length>0&&!parts.some(p=>p.functionCall),'model_invalid_output');
  const text=parts.filter(p=>typeof p.text==='string'&&!p.thought).map(p=>p.text).join('');
  assert(text.length<=15000,'model_output_too_large');
  let value;try { value=JSON.parse(text); } catch { fail('model_invalid_json'); }
  assert(value&&typeof value==='object'&&!Array.isArray(value),'model_invalid_json');
  const u=b.usageMetadata;
  assert(u&&Number.isInteger(u.promptTokenCount)&&Number.isInteger(u.candidatesTokenCount)&&Number.isInteger(u.totalTokenCount),'missing_usage_metadata');
  assert(u.promptTokenCount>=0&&u.candidatesTokenCount>=0&&u.totalTokenCount>=u.promptTokenCount+u.candidatesTokenCount,'usage_invalid_metadata');
  const usage={input_tokens:previous.input_tokens+u.promptTokenCount,
    output_tokens:previous.output_tokens+(u.totalTokenCount-u.promptTokenCount),
    model:previous.model}; // Includes thought/tool tokens in total rather than silently undercounting.
  assert(usage.input_tokens+usage.output_tokens<=12000,'usage_exceeds_budget');
  return {value,usage};
}
function exactKeys(obj,keys,code='model_invalid_schema') {
  assert(obj&&typeof obj==='object'&&!Array.isArray(obj)&&Object.keys(obj).sort().join('|')===[...keys].sort().join('|'),code);
}
function strings(value,max=6,size=500) {
  assert(Array.isArray(value)&&value.length<=max&&value.every(v=>typeof v==='string'&&v.length<=size&&!/[\u0000-\u0008]/.test(v)),'model_invalid_schema');
  return value;
}
function modelRequest(system,data,schema,maxOutputTokens) {
  // Gemini 3.5 Flash-Lite uses default minimal thinking. Deprecated sampling/budget fields are omitted.
