function schemaObject(properties) {return {type:'OBJECT',properties,required:Object.keys(properties)};}
const textSchema={type:'STRING'}, listSchema={type:'ARRAY',items:textSchema};
function cleanBody(body) {
  assert(typeof body==='string','letter_invalid_body');body=normalize(body).trim();
  assert(body.length>=100&&body.length<=3500&&words(body)<=210,'letter_invalid_length');
  assert(!/```|\*\*|\[(?:your|candidate|insert|name|company|role|date|address|email|phone)[^\]]*\]|<(?:EMAIL_ADDRESS|PHONE_NUMBER|NAME|PERSON)>/i.test(body),'letter_placeholders');
  assert(!/^(?:dear|to the)\b/i.test(body)&&!/^\s*(?:sincerely|regards|yours truly|yours faithfully)\b/im.test(body),'letter_body_only');
  assert(!/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(body),'letter_invalid_characters');
